    cookie_section3_google_title: 'Google Analytics:',
    cookie_section3_google_desc: 'Dieser Web-Analytics-Service verwendet Cookies zur Analyse der Website-Nutzung. Daten einschließlich Ihrer IP-Adresse werden an Google-Server in den Vereinigten Staaten übertragen. Google anonymisiert IP-Adressen aus der EU. Sie können sich mit dem hier verfügbaren Browser-Plugin abmelden: {google_optout}<br />Weitere Details: {google_terms} | {google_privacy}',
    cookie_section3_doubleclick_title: 'DoubleClick (Google AdSense):',
