    cookie_section3_facebook_title: 'Facebook:',
    cookie_section3_facebook_desc: 'Social Media-Plugins ermöglichen die Verbindung mit Ihrem sozialen Netzwerk, und Cookies können Ihr Profil verbessern oder Daten zu Facebook beitragen, wie in deren Datenschutzrichtlinie beschrieben.',
    cookie_section3_youtube_title: 'YouTube:',
